$metrics=$isDashboard?[
    ['Community members',number_format((int)($data['users'] ?? 0)),'users','All customer, provider and admin profiles'],
    ['Active bookings',number_format((int)($data['active_bookings'] ?? 0)),'calendar','Pending, confirmed or in progress'],
    ['Gross collected',money($data['gross_collected'] ?? 0),'wallet','Successful payments in selected period'],
    ['Awaiting verification',number_format((int)($data['pending_providers'] ?? 0)),'shield','Provider applications requiring review']
]:[
    ['Bookings created',number_format((int)($data['bookings'] ?? 0)),'calendar','Created during the selected period'],
