    ['Gross collected',money($data['gross_collected'] ?? 0),'wallet','Collected before deducting refunds'],
    ['Platform fees',money($data['platform_fees'] ?? 0),'chart','Fees recorded in provider earnings']
];
$daily=$data['daily'] ?? []; $maxValue=1; foreach($daily as $day) $maxValue=max($maxValue,(int)$day['bookings'],(int)$day['users']);
$yMax=max(4,(int)(ceil($maxValue/4)*4)); $plotWidth=690; $plotHeight=190; $left=45; $top=25; $bottom=$top+$plotHeight; $countDays=count($daily); $bookingPoints=[]; $userPoints=[];
foreach($daily as $index=>$day) { $x=$countDays>1?$left+($index/($countDays-1))*$plotWidth:$left+$plotWidth/2; $bookingPoints[]=round($x,2).','.round($bottom-((int)$day['bookings']/$yMax)*$plotHeight,2); $userPoints[]=round($x,2).','.round($bottom-((int)$day['users']/$yMax)*$plotHeight,2); }
?>
