    <?php if($daily): ?><div class="chart-wrap"><svg class="trend-chart" viewBox="0 0 760 265" role="img" aria-labelledby="chart-title chart-desc"><title id="chart-title">Daily community activity</title><desc id="chart-desc">Bookings and new users from <?= e($rangeFrom) ?> to <?= e($rangeTo) ?>. Exact values are available in the data table below.</desc><defs><linearGradient id="booking-fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#f97316" stop-opacity="0.2"/><stop offset="100%" stop-color="#f97316" stop-opacity="0.01"/></linearGradient></defs>
    <?php for($tick=0;$tick<=4;$tick++): $y=$bottom-$tick/4*$plotHeight; ?><line class="chart-gridline" x1="<?= $left ?>" y1="<?= $y ?>" x2="<?= $left+$plotWidth ?>" y2="<?= $y ?>"/><text class="chart-axis-label" x="30" y="<?= $y+4 ?>" text-anchor="end"><?= (int)($yMax*$tick/4) ?></text><?php endfor; ?>
    <?php if($countDays>1): ?><polygon points="<?= $left ?>,<?= $bottom ?> <?= e(implode(' ',$bookingPoints)) ?> <?= $left+$plotWidth ?>,<?= $bottom ?>" fill="url(#booking-fill)"/><?php endif; ?>
    <polyline class="chart-users-line" points="<?= e(implode(' ',$userPoints)) ?>"/><polyline class="chart-booking-line" points="<?= e(implode(' ',$bookingPoints)) ?>"/>
    <?php if($countDays===1): ?><circle cx="<?= $left+$plotWidth/2 ?>" cy="<?= $bottom-((int)$daily[0]['bookings']/$yMax)*$plotHeight ?>" r="4" fill="#ea580c"/><circle cx="<?= $left+$plotWidth/2 ?>" cy="<?= $bottom-((int)$daily[0]['users']/$yMax)*$plotHeight ?>" r="4" fill="#64748b"/><?php endif; ?>
    <?php $labelIndices=$countDays===1?[0]:array_unique([0,(int)floor(($countDays-1)/3),(int)floor(2*($countDays-1)/3),$countDays-1]);foreach($labelIndices as $index): $x=$countDays>1?$left+($index/($countDays-1))*$plotWidth:$left+$plotWidth/2; ?><text class="chart-axis-label" x="<?= round($x,2) ?>" y="245" text-anchor="middle"><?= e(localDate($daily[$index]['date'],'d M')) ?></text><?php endforeach; ?></svg></div>
