    <?php foreach([['providers','Provider applications','Review credentials',$data['pending_providers'] ?? 0,'shield'],['disputes','Open disputes','Review service issues',$data['open_disputes'] ?? 0,'alert'],['reviews','Flagged reviews','Assess customer feedback',$data['flagged_reviews'] ?? 0,'star']] as $item): ?><a class="attention-item" href="<?= e(url($item[0],$item[0]==='providers'?['status'=>'Pending']:($item[0]==='reviews'?['status'=>'Flagged']:[]))) ?>"><span class="attention-icon"><?= viewIcon($item[4]) ?></span><span class="attention-copy"><strong><?= e($item[1]) ?></strong><span><?= e($item[2]) ?></span></span><span class="attention-count"><?= number_format((int)$item[3]) ?></span><?= viewIcon('arrow') ?></a><?php endforeach; ?>
