<?php
$revenueMax=0.0;foreach($daily as $day) $revenueMax=max($revenueMax,(float)($day['gross_collected'] ?? 0));
$revenueStep=$revenueMax>0?max(0.01,pow(10,floor(log10($revenueMax/4)))):1;
$revenueYMax=$revenueMax>0?ceil($revenueMax/(4*$revenueStep))*4*$revenueStep:4;
$revenueLeft=92;$revenueWidth=643;$revenuePoints=[];
foreach($daily as $index=>$day){$x=$countDays>1?$revenueLeft+$index/($countDays-1)*$revenueWidth:$revenueLeft+$revenueWidth/2;$revenuePoints[]=round($x,2).','.round($bottom-((float)($day['gross_collected'] ?? 0)/$revenueYMax)*$plotHeight,2);}
