te($daily[$index]['date'],'d M')) ?></text><?php endforeach; ?></svg></div><details class="chart-data"><summary>View exact daily collections</summary><div class="table-wrap"><table><thead><tr><th scope="col">Payment date</th><th scope="col">Gross collected (MYR)</th></tr></thead><tbody><?php foreach($daily as $day): ?><tr><td><?= e(localDate($day['date'],'d M Y')) ?></td><td class="amount"><?= e(money($day['gross_collected'] ?? 0)) ?></td></tr><?php endforeach; ?></tbody></table></div></details><?php else: ?><div class="empty-state compact"><span class="empty-icon"><?= viewIcon('wallet') ?></span><h3>No collection data available</h3><p>Choose a reporting period to view payment collections.</p></div><?php endif; ?></section>
<section class="panel popularity-panel" aria-labelledby="popularity-title"><div class="panel-heading"><div><h2 id="popularity-title">Service popularity</h2><p>Booking share by service category</p></div></div><?php if($categories): ?><?php if($categoryTotal>0): ?><div class="popularity-chart"><svg class="donut-chart" viewBox="0 0 200 200" role="img" aria-labelledby="popularity-chart-title popularity-chart-desc"><title id="popularity-chart-title">Service categories by booking share</title><desc id="popularity-chart-desc"><?= number_format($categoryTotal) ?> bookings across <?= count($categories) ?> categories. Counts, completed bookings and collections are listed in the table below.</desc><circle cx="100" cy="100" r="70" fill="none" stroke="#f1f5f9" stroke-width="22"/><?php $offset=0.0;$circumference=2*M_PI*70;foreach($categories as $index=>$category):$segment=((int)$category['bookings']/$categoryTotal)*$circumference; ?><circle cx="100" cy="100" r="70" fill="none" stroke="<?= e($palette[$index%count($palette)]) ?>" stroke-width="22" stroke-dasharray="<?= round($segment,3) ?> <?= round($circumference-$segment,3) ?>" stroke-dashoffset="<?= round(-$offset,3) ?>" transform="rotate(-90 100 100)"/><?php $offset+=$segment;endforeach; ?><text class="donut-total" x="100" y="102" text-anchor="middle"><?= number_format($categoryTotal) ?></text><text class="donut-label" x="100" y="124" text-anchor="middle">bookings</text></svg><div class="popularity-legend"><?php foreach(array_slice($categories,0,5) as $index=>$category): ?><div><svg class="category-color" width="9" height="9" viewBox="0 0 9 9" aria-hidden="true"><rect width="9" height="9" rx="2" fill="<?= e($palette[$index%count($palette)]) ?>"/></svg><span><?= e($category['category_name']) ?></span><strong><?= e(number_format((int)$category['bookings']/$categoryTotal*100,1)) ?>%</strong></div><?php endforeach; ?><?php if(count($categories)>5): ?><p>All <?= count($categories) ?> categories are listed below.</p><?php endif; ?></div></div><?php else: ?><div class="inline-empty popularity-empty">No bookings were created in this period. Collections for earlier bookings are listed below.</div><?php endif; ?><div class="table-wrap"><table><thead><tr><th scope="col">Category</th><th scope="col">Bookings</th><th scope="col">Completed</th><th scope="col">Collected</th></tr></thead><tbody><?php foreach($categories as $index=>$category): ?><tr><td><span class="category-table-label"><svg class="category-color" width="9" height="9" viewBox="0 0 9 9" aria-hidden="true"><rect width="9" height="9" rx="2" fill="<?= e($palette[$index%count($palette)]) ?>"/></svg><?= e($category['category_name']) ?></span></td><td><?= number_format((int)$category['bookings']) ?></td><td><?= number_format((int)($category['completed'] ?? 0)) ?></td><td class="amount"><?= e(money($category['gross_collected'] ?? 0)) ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty-state compact"><span class="empty-icon"><?= viewIcon('layers') ?></span><h3>No bookings for these filters</h3><p>Category popularity appears when service bookings are created.</p></div><?php endif; ?></section></div>
